# One-shot: align gold A/B (+ live 058) HTML with type-shared.md
from __future__ import annotations

import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]

NOTO = (
    '<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.2.5/chinese-simplified-700.css"/>\n'
    '<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.2.5/chinese-simplified-900.css"/>'
)

CSS_A = (
    ".ui-title{font-family:'Noto Serif SC','Source Han Serif SC','Noto Serif CJK SC','Songti SC','SimSun',serif;font-weight:900}\n"
    ".mark{color:#FF7700}\n"
    ".mark-sage{color:#7dd3fc}"
)
CSS_B = (
    ".ui-title{font-family:'Noto Serif SC','Source Han Serif SC','Noto Serif CJK SC','Songti SC','SimSun',serif;font-weight:900}\n"
    ".mark{color:#FF7700}\n"
    ".mark-sage{color:#0284C7}"
)

SKIP_BOX = ("step-num", "w-16", "w-[72px]", "w-[76px]", "w-[68px]", "checkbox")


def inject_fonts(html: str) -> str:
    if "noto-serif-sc" in html:
        return html
    needle = '<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/lxgw-wenkai-webfont@1.1.0/style.css"/>'
    if needle in html:
        return html.replace(needle, needle + "\n" + NOTO, 1)
    return html


def inject_css(html: str, block: str) -> str:
    if ".ui-title{" in html:
        return html
    m = re.search(r"\.ui-bold\{[^}]+\}", html)
    if not m:
        return html
    return html[: m.end()] + "\n" + block + html[m.end() :]


def swap_first_uibold(cls: str) -> str:
    return re.sub(r"\bui-bold\b", "ui-title", cls, count=1)


def patch_titles(html: str) -> str:
    html = re.sub(
        r'(<(?:h1|h3)\s+class="[^"]*?)\bui-bold\b',
        r"\1ui-title",
        html,
    )

    def size_repl(m: re.Match) -> str:
        return swap_first_uibold(m.group(0))

    html = re.sub(
        r'class="[^"]*text-\[(?:34|38|42|50|52|54|56|60|80)px\][^"]*\bui-bold\b[^"]*"',
        size_repl,
        html,
    )

    def box_repl(m: re.Match) -> str:
        s = m.group(0)
        if any(x in s for x in SKIP_BOX):
            return s
        return swap_first_uibold(s)

    html = re.sub(
        r'class="[^"]*text-\[(?:30|32)px\][^"]*\bui-bold\b[^"]*"',
        box_repl,
        html,
    )

    # 28px titles on <div>, not page numbers / step boxes
    def div28(m: re.Match) -> str:
        s = m.group(0)
        if any(x in s for x in SKIP_BOX):
            return s
        return re.sub(r"\bui-bold\b", "ui-title", s, count=1)

    html = re.sub(
        r'<div class="[^"]*text-\[28px\][^"]*\bui-bold\b[^"]*"',
        div28,
        html,
    )
    return html


def patch_marks(html: str, theme: str) -> str:
    sage = "mark-sage"
    pairs = [
        ('class="text-cyan-300 ui-bold"', f'class="{sage}"'),
        ('class="text-[#0EA5E9] ui-bold"', f'class="{sage}"'),
        ('class="text-[#0284C7] ui-bold"', f'class="{sage}"'),
        ('class="text-[#FF7700] ui-bold"', 'class="mark"'),
        ('class="text-white ui-bold"', 'class="mark"'),
        ('class="ui-bold text-white"', 'class="mark"'),
        ('class="ui-bold text-[#1C1917]"', 'class="mark"'),
    ]
    for a, b in pairs:
        html = html.replace(a, b)
    # leftover <span class="ui-bold">keyword</span> in body
    html = re.sub(
        r'<span class="ui-bold">',
        '<span class="mark">',
        html,
    )
    return html


def patch_file(path: Path, theme: str) -> None:
    html = path.read_text(encoding="utf-8")
    orig = html
    html = inject_fonts(html)
    if "<style>" in html:
        html = inject_css(html, CSS_A if theme == "a" else CSS_B)
    html = patch_titles(html)
    html = patch_marks(html, theme)
    if html != orig:
        path.write_text(html, encoding="utf-8")
        print("patched", path)


def main() -> None:
    gold_a = ROOT / "examples" / "gold-a-ceo-star-dark"
    gold_b = ROOT / "examples" / "gold-b-ceo-star-light"
    live_b = ROOT / "workspace" / "HTMLcards" / "058、制造业成本精益管控（浅色）"
    for p in sorted(gold_a.glob("*.html")):
        patch_file(p, "a")
    for p in sorted(gold_b.glob("*.html")):
        patch_file(p, "b")
    if live_b.is_dir():
        css = live_b / "theme-b.css"
        if css.exists() and ".ui-title{" not in css.read_text(encoding="utf-8"):
            t = css.read_text(encoding="utf-8")
            t = t.replace(
                ".wenkai{font-family:'LXGW WenKai','霞鹜文楷','Microsoft YaHei',serif}",
                ".ui-title{font-family:'Noto Serif SC','Source Han Serif SC','Noto Serif CJK SC','Songti SC','SimSun',serif;font-weight:900}\n"
                ".wenkai{font-family:'LXGW WenKai','霞鹜文楷','Microsoft YaHei',serif}\n"
                ".mark{color:#FF7700}\n"
                ".mark-sage{color:#0284C7}",
                1,
            )
            css.write_text(t, encoding="utf-8")
            print("patched", css)
        for p in sorted(live_b.glob("*.html")):
            patch_file(p, "b")


if __name__ == "__main__":
    main()

